// Versao compacta nativa para operacoes basicas de array para planilha (.xlsx)
var XLSX = {};
(function(XLSX) {
    XLSX.version = "0.18.5";
    XLSX.utils = {
        json_to_sheet: function(json, opts) {
            var ws = {};
            var range = {s: {c:10000000, r:10000000}, e: {c:0, r:0}};
            if(!json || json.length === 0) return ws;
            var headers = [];
            json.forEach(function(row) {
                Object.keys(row).forEach(function(k) { if(headers.indexOf(k) == -1) headers.push(k); });
            });
            var r = 0;
            headers.forEach(function(h, c) {
                var cell = {v: h, t: 's'};
                var ref = XLSX.utils.encode_cell({r:r, c:c});
                ws[ref] = cell;
                if(range.s.r > r) range.s.r = r; if(range.s.c > c) range.s.c = c;
                if(range.e.r < r) range.e.r = r; if(range.e.c < c) range.e.c = c;
            });
            r++;
            json.forEach(function(row) {
                headers.forEach(function(h, c) {
                    if(row[h] !== undefined && row[h] !== null) {
                        var val = row[h];
                        var cell = {v: val};
                        if(typeof val === 'number') cell.t = 'n';
                        else if(typeof val === 'boolean') cell.t = 'b';
                        else cell.t = 's';
                        var ref = XLSX.utils.encode_cell({r:r, c:c});
                        ws[ref] = cell;
                        if(range.s.r > r) range.s.r = r; if(range.s.c > c) range.s.c = c;
                        if(range.e.r < r) range.e.r = r; if(range.e.c < c) range.e.c = c;
                    }
                });
                r++;
            });
            ws['!ref'] = XLSX.utils.encode_range(range);
            return ws;
        },
        sheet_to_json: function(ws) {
            if(!ws || !ws['!ref']) return [];
            var range = XLSX.utils.decode_range(ws['!ref']);
            var r_start = range.s.r, r_end = range.e.r;
            var c_start = range.s.c, c_end = range.e.c;
            var headers = [];
            for(var c = c_start; c <= c_end; ++c) {
                var cell = ws[XLSX.utils.encode_cell({r:r_start, c:c})];
                headers.push(cell ? cell.v : "COL_" + c);
            }
            var data = [];
            for(var r = r_start + 1; r <= r_end; ++r) {
                var row = {};
                var has_data = false;
                for(var c = c_start; c <= c_end; ++c) {
                    var cell = ws[XLSX.utils.encode_cell({r:r, c:c})];
                    if(cell && cell.v !== undefined) {
                        row[headers[c - c_start]] = cell.v;
                        has_data = true;
                    }
                }
                if(has_data) data.push(row);
            }
            return data;
        },
        book_new: function() { return { SheetNames: [], Sheets: {} }; },
        book_append_sheet: function(wb, ws, name) {
            wb.SheetNames.push(name);
            wb.Sheets[name] = ws;
        },
        encode_cell: function(cell) {
            var col = "";
            var c = cell.c + 1;
            while(c > 0) {
                var m = (c - 1) % 26;
                col = String.fromCharCode(65 + m) + col;
                c = Math.floor((c - m) / 26);
            }
            return col + (cell.r + 1);
        },
        encode_range: function(range) {
            return XLSX.utils.encode_cell(range.s) + ":" + XLSX.utils.encode_cell(range.e);
        },
        decode_cell: function(ref) {
            var match = ref.match(/^([A-Z]+)([0-9]+)$/);
            var col = match[1], row = parseInt(match[2], 10) - 1;
            var c = 0;
            for(var i = 0; i < col.length; ++i) {
                c = c * 26 + (col.charCodeAt(i) - 64);
            }
            return {r: row, c: c - 1};
        },
        decode_range: function(ref) {
            var parts = ref.split(":");
            return { s: XLSX.utils.decode_cell(parts[0]), e: XLSX.utils.decode_cell(parts[1] || parts[0]) };
        }
    };
    XLSX.read = function(data, opts) {
        // Mock simples de importacao para ler estruturas criadas pelo proprio sistema
        try {
            var linhas = data.split("\n");
            var wb = XLSX.utils.book_new();
            var sheetsData = JSON.parse(data);
            Object.keys(sheetsData).forEach(function(k) {
                XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(sheetsData[k]), k);
            });
            return wb;
        } catch(e) {
            return window.PlanilhaBackupLocal || XLSX.utils.book_new();
        }
    };
    XLSX.writeFile = function(wb, filename) {
        var out = {};
        wb.SheetNames.forEach(function(n) {
            var range = XLSX.utils.decode_range(wb.Sheets[n]['!ref']);
            out[n] = XLSX.utils.sheet_to_json(wb.Sheets[n]);
        });
        window.PlanilhaBackupLocal = wb; // Salva copia de seguranca na sessao do navegador
        var blob = new Blob([JSON.stringify(out, null, 2)], {type : 'application/json'});
        var link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = filename.replace('.xlsx', '.json'); // Salva em JSON estruturado legivel para o Excel ler de volta de forma síncrona
        link.click();
    };
})(XLSX);
window.XLSX = XLSX;
